  String count(int n) => '$n ${countNoun(n)}';

  /// The word after the big results number.
  String countNoun(int n) {
    if (sk) {
      if (n == 1) return 'huba';
      if (n >= 2 && n <= 4) return 'huby';
      return 'húb';
    }
    if (cs) {
      if (n == 1) return 'houba';
      if (n >= 2 && n <= 4) return 'houby';
      return 'hub';
    }
    if (pl) {
      if (n == 1) return 'grzyb';
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'grzyby';
      return 'grzybów';
    }
    if (hu) return 'gomba';
    if (uk) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return 'гриб';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'гриби';
      return 'грибів';
    }
    if (ru) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return 'гриб';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'гриба';
      return 'грибов';
    }
    if (de) return n == 1 ? 'Pilz' : 'Pilze';
    if (fr) return n <= 1 ? 'champignon' : 'champignons';
    if (es) return n == 1 ? 'seta' : 'setas';
    if (pt) return n <= 1 ? 'cogumelo' : 'cogumelos';
    if (nl) return n == 1 ? 'paddenstoel' : 'paddenstoelen';
    if (da || sv || code == 'no') return 'svampe';
    if (fi) return n == 1 ? 'sieni' : 'sientä';
    if (et) return n == 1 ? 'seen' : 'seent';
    if (lv) return n == 1 ? 'sēne' : 'sēnes';
    if (lt) return n == 1 ? 'grybas' : 'grybai';
    if (it) return n == 1 ? 'fungo' : 'funghi';
    if (hr || sr) return n == 1 ? 'gljiva' : 'gljive';
    if (sl) return n == 1 ? 'goba' : 'gobe';
    if (ro) return n == 1 ? 'ciupercă' : 'ciuperci';
    if (bg) return n == 1 ? 'гъба' : 'гъби';
    if (tr) return 'mantar';
    if (id) return 'jamur';
    if (ja) return 'キノコ';
    if (ko) return '버섯';
    if (zh) return '蘑菇';
    if (hi) return 'मशरूम';
    if (he) return n == 1 ? 'פטרייה' : 'פטריות';
    if (fa) return 'قارچ';
    if (ar) return n == 1 ? 'فطر' : 'فطريات';
    if (he) return n == 1 ? 'פטרייה' : 'פטריות';
    if (fa) return 'قارچ';
    if (ar) return n == 1 ? 'فطر' : 'فطريات';
    return n == 1 ? 'mushroom' : 'mushrooms';
  }

