  String bookCounts(String mushrooms, int families) {
    final word = switch (code) {
      'sk' => switch (families) {
        1 => 'čeľaď',
        >= 2 && <= 4 => 'čeľade',
        _ => 'čeľadí',
      },
      'cs' => switch (families) {
        1 => 'čeleď',
        >= 2 && <= 4 => 'čeledi',
        _ => 'čeledí',
      },
      'pl' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (families == 1) return 'rodzina';
        if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'rodziny';
        return 'rodzin';
      }(),
      'hu' => 'család',
      'uk' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'родина';
        if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'родини';
        return 'родин';
      }(),
      'ru' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'семейство';
        if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'семейства';
        return 'семейств';
      }(),
      'de' => families == 1 ? 'Familie' : 'Familien',
      'fr' => families <= 1 ? 'famille' : 'familles',
      'es' => families == 1 ? 'familia' : 'familias',
      'pt' => families <= 1 ? 'família' : 'famílias',
      'nl' => families == 1 ? 'familie' : 'families',
      'da' => families == 1 ? 'familie' : 'familier',
      'sv' => families == 1 ? 'familj' : 'familjer',
      'no' => families == 1 ? 'familie' : 'familier',
      'fi' => families == 1 ? 'heimo' : 'heimoa',
      'et' => families == 1 ? 'sugukond' : 'sugukonda',
      'lv' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'dzimta';
        if (m10 == 0 || (m100 >= 11 && m100 <= 19)) return 'dzimtu';
        return 'dzimtas';
      }(),
      'lt' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'šeima';
        if (m10 >= 2 && m10 <= 9 && (m100 < 10 || m100 >= 20)) return 'šeimos';
        return 'šeimų';
      }(),
      'it' => families == 1 ? 'famiglia' : 'famiglie',
      'hr' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'porodica';
        if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'porodice';
        return 'porodica';
      }(),
      'sl' => () {
        final m100 = families % 100;
        if (m100 == 1) return 'družina';
        if (m100 == 2) return 'družini';
        if (m100 == 3 || m100 == 4) return 'družine';
        return 'družin';
      }(),
      'sr' => () {
        final m10 = families % 10;
        final m100 = families % 100;
        if (m10 == 1 && m100 != 11) return 'породица';
        if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'породице';
        return 'породица';
      }(),
      'ro' => () {
        if (families == 1) return 'familie';
        final m100 = families % 100;
        if (families == 0 || (m100 >= 1 && m100 <= 19)) return 'familii';
        return 'de familii';
      }(),
      'bg' => families == 1 ? 'семейство' : 'семейства',
      'tr' => 'familya',
      'id' => 'famili',
      'ja' => '科',
      'ko' => '과',
      'zh' => '科',
      'hi' => 'कुल',
      'he' => families == 1 ? 'משפחה' : 'משפחות',
      'fa' => 'خانواده',
      'ar' => families == 1 ? 'فصيلة' : 'فصائل',
      _ => families == 1 ? 'family' : 'families',
    };
    return '$mushrooms · $families $word';
  }

