  String photoCount(int n) {
    if (sk) return n == 1 ? '1 fotografia' : '$n fotografií';
    if (cs) {
      if (n == 1) return '1 fotografie';
      if (n >= 2 && n <= 4) return '$n fotografie';
      return '$n fotografií';
    }
    if (pl) {
      if (n == 1) return '1 zdjęcie';
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n zdjęcia';
      return '$n zdjęć';
    }
    if (hu) return '$n fénykép';
    if (uk) return '$n фото';
    if (ru) return '$n фото';
    if (de) return n == 1 ? '1 Foto' : '$n Fotos';
    if (fr || es || pt) return n <= 1 ? '$n photo' : '$n photos';
    if (nl) return n == 1 ? '1 foto' : '$n foto’s';
    if (da || sv || code == 'no') return '$n fotos';
    if (fi) return n == 1 ? '1 kuva' : '$n kuvaa';
    if (et) return n == 1 ? '1 foto' : '$n fotot';
    if (lv) return '$n foto';
    if (lt) return n == 1 ? '1 nuotrauka' : '$n nuotraukos';
    if (it) return n == 1 ? '1 foto' : '$n foto';
    if (hr || sr) return '$n fotografija';
    if (sl) return '$n fotografij';
    if (ro) return n == 1 ? '1 fotografie' : '$n fotografii';
    if (bg) return n == 1 ? '1 снимка' : '$n снимки';
    if (tr) return '$n fotoğraf';
    if (id) return n == 1 ? '1 foto' : '$n foto';
    if (ja) return '$n 枚の写真';
    if (ko) return '사진 $n장';
    if (zh) return '$n 張照片';
    if (hi) return '$n फ़ोटो';
    if (he) return n == 1 ? 'תמונה אחת' : '$n תמונות';
    if (fa) return '$n عکس';
    if (ar) return n == 1 ? 'صورة واحدة' : '$n صور';
    return n == 1 ? '1 photo' : '$n photos';
  }

