  String _shortMonthDay(DateTime day) {
    final m = shortMonth(day.month);
    return switch (code) {
      'sk' || 'cs' => '${day.day}. ${m.replaceAll('.', '')}',
      'hu' => '$m ${day.day}.',
      'de' || 'pl' || 'uk' || 'ru' || 'da' || 'no' || 'fi' || 'et' || 'lv' || 'lt' || 'hr' || 'sl' || 'sr' || 'bg' =>
        '${day.day}. $m',
      'fr' || 'es' || 'pt' || 'nl' || 'sv' || 'it' || 'ro' || 'tr' || 'id' || 'hi' || 'he' || 'fa' || 'ar' =>
        '${day.day} $m',
      'ja' || 'zh' => '${day.month}月${day.day}日',
      'ko' => '${day.month}월 ${day.day}일',
      _ => '$m ${day.day}',
    };
  }

  String namesLeft(int count) {
    final n = count < 0 ? 0 : count;
    if (sk) {
      if (n == 1) return '1 určenie zostáva';
      if (n >= 2 && n <= 4) return '$n určenia zostávajú';
      return '$n určení zostáva';
    }
    if (cs) {
      if (n == 1) return '1 určení zbývá';
      if (n >= 2 && n <= 4) return '$n určení zbývají';
      return '$n určení zbývá';
    }
    if (pl) {
      if (n == 1) return 'Pozostało 1 oznaczenie';
      final m10 = n % 10;
      final m100 = n % 100;
