  String seenFinds(int n) {
    if (sk) {
      if (n == 1) return '1 nález';
      if (n >= 2 && n <= 4) return '$n nálezy';
      return '$n nálezov';
    }
    if (cs) {
      if (n == 1) return '1 nález';
      if (n >= 2 && n <= 4) return '$n nálezy';
      return '$n nálezů';
    }
    if (pl) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (n == 1) return '1 znalezisko';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n znaleziska';
      return '$n znalezisk';
    }
    if (hu) return '$n találat';
    if (uk) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n знахідка';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n знахідки';
      return '$n знахідок';
    }
    if (ru) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n находка';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n находки';
      return '$n находок';
    }
    if (de) return n == 1 ? '1 Fund' : '$n Funde';
    if (fr || pt) return n <= 1 ? '$n observation' : '$n observations';
    if (es) return n == 1 ? '1 hallazgo' : '$n hallazgos';
    if (nl) return n == 1 ? '1 waarneming' : '$n waarnemingen';
    if (da || sv) return n == 1 ? (da ? '1 fund' : '1 fynd') : (da ? '$n fund' : '$n fynd');
    if (code == 'no') return n == 1 ? '1 funn' : '$n funn';
    if (fi) return n == 1 ? '1 havainto' : '$n havaintoa';
    if (et) return n == 1 ? '1 leid' : '$n leidu';
    if (lv) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n atradums';
      if (m10 == 0 || (m100 >= 11 && m100 <= 19)) return '$n atradumu';
      return '$n atradumi';
    }
    if (lt) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n radinys';
      if (m10 >= 2 && m10 <= 9 && (m100 < 10 || m100 >= 20)) return '$n radiniai';
      return '$n radinių';
    }
    if (it) return n <= 1 ? '$n ritrovamento' : '$n ritrovamenti';
    if (hr) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n nalaz';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n nalaza';
      return '$n nalaza';
    }
    if (sl) {
      final m100 = n % 100;
      if (m100 == 1) return '$n najdba';
      if (m100 == 2) return '$n najdbi';
      if (m100 == 3 || m100 == 4) return '$n najdbe';
      return '$n najdb';
    }
    if (sr) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return '$n налаз';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n налаза';
      return '$n налаза';
    }
    if (ro) {
      if (n == 1) return '1 observație';
      final m100 = n % 100;
      if (n == 0 || (m100 >= 1 && m100 <= 19)) return '$n observații';
      return '$n de observații';
    }
    if (bg) return n == 1 ? '1 находка' : '$n находки';
    if (tr) return '$n buluntu';
    if (id) return '$n temuan';
    if (ja) return '$n 件の記録';
    if (ko) return '$n개의 발견';
    if (zh) return '$n 筆紀錄';
    if (hi) return '$n खोजें';
    if (he) return n == 1 ? 'מציאה אחת' : '$n מציאות';
    if (fa) return '$n یافته';
    if (ar) return n == 1 ? 'مكتشف واحد' : '$n مكتشفات';
    return n == 1 ? '1 find' : '$n finds';
  }

