  String seenHiddenCount(int n) {
    if (sk) {
      if (n == 1) return '1 zdieľaný skrytý';
      if (n >= 2 && n <= 4) return '$n zdieľané skryté';
      return '$n zdieľaných skrytých';
    }
    if (cs) {
      if (n == 1) return '1 sdílený skrytý';
      if (n >= 2 && n <= 4) return '$n sdílené skryté';
      return '$n sdílených skrytých';
    }
    if (pl) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (n == 1) return '1 udostępniony ukryty';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return '$n udostępnione ukryte';
      return '$n udostępnionych ukrytych';
    }
    if (hu) return '$n megosztott rejtve';
    if (uk) return '$n поширених прихованих';
    if (ru) return '$n опубликованных скрыто';
    if (de) {
      return n == 1
          ? '1 geteilter Fund ausgeblendet'
          : '$n geteilte Funde ausgeblendet';
    }
    if (fr || pt) return n <= 1 ? '$n partagé masqué' : '$n partagés masqués';
    if (es) return n == 1 ? '1 compartido oculto' : '$n compartidos ocultos';
    if (nl) return n == 1 ? '1 gedeelde verborgen' : '$n gedeelde verborgen';
    if (da || code == 'no') return n == 1 ? '1 delt skjult' : '$n delte skjult';
    if (sv) return n == 1 ? '1 delat dolt' : '$n delade dolda';
    if (fi) return n == 1 ? '1 jaettu piilotettu' : '$n jaettua piilotettu';
    if (et) return n == 1 ? '1 jagatud peidetud' : '$n jagatud peidetud';
    if (lv) return n == 1 ? '1 kopīgots paslēpts' : '$n kopīgoti paslēpti';
    if (lt) return n == 1 ? '1 bendrintas paslėptas' : '$n bendrinti paslėpti';
    if (it) return n <= 1 ? '$n condiviso nascosto' : '$n condivisi nascosti';
    if (hr) return n == 1 ? '1 dijeljen skriveni' : '$n dijeljenih skrivenih';
    if (sl) return n == 1 ? '1 deljena skrita' : '$n deljenih skritih';
    if (sr) return n == 1 ? '1 дељен скривени' : '$n дељених скривених';
    if (ro) return n == 1 ? '1 partajată ascunsă' : '$n partajate ascunse';
    if (bg) return n == 1 ? '1 споделена скрита' : '$n споделени скрити';
    if (tr) return '$n paylaşılan gizli';
    if (id) return '$n dibagikan disembunyikan';
    if (ja) return '$n 件の共有を非表示';
    if (ko) return '숨겨진 공유 항목 $n개';
    if (zh) return '$n 個已分享項目已隱藏';
    if (hi) return '$n साझा छुपाए गए';
    if (he) return n == 1 ? 'שותף אחד מוסתר' : '$n ששותפו מוסתרים';
    if (fa) return '$n مورد هم‌رسانی‌شده پنهان';
    if (ar) return n == 1 ? 'مُشارَكة واحدة مخفية' : '$n مُشارَكات مخفية';
    return n == 1 ? '1 shared hidden' : '$n shared hidden';
  }

