  String sightingsShared(int n) {
    if (sk) {
      if (n == 1) return '1 zdieľané používateľmi';
      if (n >= 2 && n <= 4) return '$n zdieľané používateľmi';
      return '$n zdieľaných používateľmi';
    }
    if (cs) {
      if (n == 1) return '1 sdílené uživateli';
      if (n >= 2 && n <= 4) return '$n sdílená uživateli';
      return '$n sdílených uživateli';
    }
    if (pl) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (n == 1) return '1 udostępniona przez użytkowników';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) {
        return '$n udostępnione przez użytkowników';
      }
      return '$n udostępnionych przez użytkowników';
    }
    if (hu) return 'az alkalmazás felhasználóitól: $n';
    if (uk) return 'від користувачів застосунку: $n';
    if (ru) return 'от пользователей приложения: $n';
    if (de) return '$n von App-Nutzern geteilt';
    if (fr) return 'partagés dans l’application : $n';
    if (es) return 'compartidos en la aplicación: $n';
    if (pt) return 'partilhados na aplicação: $n';
    if (nl) return '$n gedeeld door app-gebruikers';
    if (da) return '$n delt af app-brugere';
    if (sv) return '$n som appanvändare delat';
    if (code == 'no') return '$n delt av appbrukere';
    if (fi) return 'sovelluksen käyttäjiltä: $n';
    if (et) return 'rakenduse kasutajatelt: $n';
    if (lv) return 'lietotāju kopīgots: $n';
    if (lt) return 'bendrino programėlės naudotojai: $n';
    if (it) return 'condivisi nell’app: $n';
    if (hr) return 'korisnici dijele: $n';
    if (sl) return 'uporabniki delijo: $n';
    if (sr) return 'корисници деле: $n';
    if (ro) return 'partajate în aplicație: $n';
    if (bg) return 'споделени от потребители: $n';
    if (tr) return 'Uygulama kullanıcıları paylaştı: $n';
    if (id) return '$n dibagikan oleh pengguna aplikasi';
    if (ja) return 'アプリ利用者が共有：$n';
    if (ko) return '앱 사용자가 공유: $n';
    if (zh) return '應用程式使用者分享：$n';
    if (hi) return 'ऐप उपयोगकर्ताओं द्वारा साझा: $n';
    if (he) return '$n ששותפו על ידי משתמשי האפליקציה';
    if (fa) return '$n مورد هم‌رسانی‌شده توسط کاربران برنامه';
    if (ar) return '$n مُشارَكات من مستخدمي التطبيق';
    return '$n shared by app users';
  }

