  String statsFinds(int n) {
    if (sk) {
      if (n == 1) return 'Nález';
      if (n >= 2 && n <= 4) return 'Nálezy';
      return 'Nálezov';
    }
    if (cs) {
      if (n == 1) return 'Nález';
      if (n >= 2 && n <= 4) return 'Nálezy';
      return 'Nálezů';
    }
    if (pl) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (n == 1) return 'Znalezisko';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'Znaleziska';
      return 'Znalezisk';
    }
    if (hu) return 'Találat';
    if (uk) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return 'Знахідка';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'Знахідки';
      return 'Знахідок';
    }
    if (ru) {
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 == 1 && m100 != 11) return 'Находка';
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'Находки';
      return 'Находок';
    }
    if (de) return n == 1 ? 'Fund' : 'Funde';
    if (fr || pt) return n <= 1 ? 'Observation' : 'Observations';
    if (es) return n == 1 ? 'Hallazgo' : 'Hallazgos';
    if (nl) return n == 1 ? 'Waarneming' : 'Waarnemingen';
