    if (hr || sr) return 'Nalaza';
    if (sl) return 'Najdb';
    if (ro) return n == 1 ? 'Găsire' : 'Găsiri';
    if (bg) return n == 1 ? 'Находка' : 'Находки';
    if (tr) return 'Buluntu';
