  String statsDay(DateTime when) {
    final m = shortMonth(when.month).replaceAll('.', '');
    if (sk) return '${when.day}. $m ${when.year}';
    if (hu) return '${when.year}. $m ${when.day}.';
    if (ja || zh) return '${when.year}年${when.month}月${when.day}日';
    if (ko) return '${when.year}년 ${when.month}월 ${when.day}일';
    if (cs || de || pl || uk || ru || da || code == 'no' || fi || et || lv || lt || hr || sl || sr || bg) {
      return '${when.day}. $m ${when.year}';
    }
    if (fr || es || pt || nl || sv || it || ro || tr || id || hi || he || fa || ar) {
      return '${when.day} $m ${when.year}';
    }
    return '$m ${when.day}, ${when.year}';
  }

