  String newAdded(int n) {
    if (sk) {
      if (n == 1) return 'posledná huba pridaná do atlasu';
      if (n >= 2 && n <= 4) return 'posledné $n huby pridané do atlasu';
      return 'posledných $n húb pridaných do atlasu';
    }
    if (cs) {
      if (n == 1) return 'poslední houba přidaná do atlasu';
      if (n >= 2 && n <= 4) return 'poslední $n houby přidané do atlasu';
      return 'posledních $n hub přidaných do atlasu';
    }
    if (de) {
      return n == 1
          ? 'Der letzte 1 Pilz, der dem Atlas hinzugefügt wurde'
          : 'Die letzten $n Pilze, die dem Atlas hinzugefügt wurden';
    }
    if (fr) {
      return n <= 1
          ? 'Le dernier champignon ajouté au guide'
          : 'Les $n derniers champignons ajoutés au guide';
    }
    if (pl) {
      if (n == 1) return 'Ostatni 1 grzyb dodany do atlasu';
      final m10 = n % 10;
      final m100 = n % 100;
      if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) {
        return 'Ostatnie $n grzyby dodane do atlasu';
      }
      return 'Ostatnich $n grzybów dodanych do atlasu';
    }
    if (hu) return 'Utolsó $n hozzáadott gomba a határozóban';
    if (uk) return 'Останні $n грибів, доданих до атласу';
    if (ru) return 'Последние $n грибов, добавленных в атлас';
    if (es) return n == 1 ? 'Última 1 seta añadida a la guía' : 'Últimas $n setas añadidas a la guía';
    if (pt) return n <= 1 ? 'Último cogumelo adicionado ao livro' : 'Últimos $n cogumelos adicionados ao livro';
    if (nl) return n == 1 ? 'Laatste 1 paddenstoel toegevoegd aan het boek' : 'Laatste $n paddenstoelen toegevoegd aan het boek';
    if (da) return n == 1 ? 'Sidste 1 svamp tilføjet til bogen' : 'Sidste $n svampe tilføjet til bogen';
    if (sv) return n == 1 ? 'Sista 1 svamp tillagd i boken' : 'Senaste $n svampar tillagda i boken';
    if (code == 'no') return n == 1 ? 'Siste 1 sopp lagt til i boken' : 'Siste $n sopper lagt til i boken';
    if (fi) return 'Viimeksi lisätyt $n sientä kirjaan';
    if (et) return 'Viimased $n raamatusse lisatud seent';
    if (lv) return 'Pēdējās $n grāmatai pievienotās sēnes';
    if (lt) return 'Paskutiniai $n į knygą pridėti grybai';
    if (it) return n == 1 ? 'Ultimo fungo aggiunto al libro' : 'Ultimi $n funghi aggiunti al libro';
    if (hr || sr) return 'Zadnjih $n gljiva dodanih u vodič';
    if (sl) return 'Zadnjih $n gob, dodanih v knjigo';
    if (ro) return n == 1 ? 'Ultima ciupercă adăugată în ghid' : 'Ultimele $n ciuperci adăugate în ghid';
    if (bg) return 'Последните $n гъби, добавени в справочника';
    if (tr) return 'Kitaba eklenen son $n mantar';
    if (id) return n == 1 ? '1 jamur terakhir ditambahkan ke buku' : '$n jamur terakhir ditambahkan ke buku';
    if (ja) return n == 1 ? '図鑑に最近追加された1種のキノコ' : '図鑑に最近追加された$n種のキノコ';
    if (ko) return n == 1 ? '도감에 최근 추가된 버섯 1종' : '도감에 최근 추가된 버섯 $n종';
    if (zh) return n == 1 ? '最新收錄到圖鑑的 1 種蘑菇' : '最新收錄到圖鑑的 $n 種蘑菇';
    if (hi) return n == 1 ? 'किताब में जोड़ा गया अंतिम 1 मशरूम' : 'किताब में जोड़े गए अंतिम $n मशरूम';
    if (he) return n == 1 ? 'הפטרייה האחרונה שנוספה לספר' : '$n הפטריות האחרונות שנוספו לספר';
    if (fa) return n == 1 ? 'آخرین قارچ اضافه شده به کتاب' : '$n قارچ آخر اضافه شده به کتاب';
    if (ar) return n == 1 ? 'آخر فطر أُضيف إلى الكتاب' : 'آخر $n فطريات أُضيفت إلى الكتاب';
    return n == 1
        ? 'The last 1 mushroom added to the book'
        : 'The last $n mushrooms added to the book';
  }

